import pathlib,json,collections
P=pathlib.Path(__file__).parent
lines=['# Husqvarna expansion coverage','', 'All counts are source records or catalog occurrences, not installed bolt totals. Snapshot generated from acquisition files.', '', '| US standard target | Assemblies captured / expected | Part occurrences | Catalog complete for US | Approved specification records |', '|---|---:|---:|---|---:|']
for cc in [250,450]:
 for yr in range(2022,2027):
  key=f'fc-{cc}-{yr}';d=json.loads((P/(key+'.json')).read_text());counter=collections.Counter()
  for f in P.glob(key+'-*.json'):
   if 'catalog-fields' in f.name:continue
   counter.update(x['review_status'] for x in json.loads(f.read_text()).get('facts',[]))
  lines.append(f"| FC {cc} {yr} | {len(d['assemblies'])} / {d.get('expected_assembly_count','?')} | {len(d['parts'])} | {d['catalog_complete']} | {counter['APPROVED']} |")
lines += ['', '## Remaining evidence gaps','', '- 2026 US standard applicability: official captured standard catalog is EU; OEM manual covers EU standard and US Factory Edition. Neither is promoted to US standard.', '- Catalog is the complete service-parts listing when marked complete. Kits, alternate shim sizes and common WP assortment rows do not represent simultaneously installed parts.', '- Some OEM article descriptions are abbreviated or truncate dimensions. Preserve original labels; do not invent the missing suffix or dimensions.', '- Exact torque-to-installation mapping, internal suspension service torques, material/grade, replacement rules and wear limits remain incomplete. A torque record for a named joint is not a torque assignment to every bolt of its diameter.', '- Manual conflicts: linkage thread mismatches, FC450 throttle-body clamp duplicate values, 2025 FC450 oil-pump-cover thread mismatch, malformed 2025 FC450 first-gear value. Conflict rows cannot become runtime specifications.', '- Maintenance intervals and full rebuild procedures need further exact-target evidence review. No paid or unauthorized manual access used.', '- Aftermarket settings are not substituted for stock specifications; none needed to establish the current OEM records.', '', '## Verification','', '- Original OEM PDF scope pages and all approved torque/engine/suspension/chassis table pages visually reviewed.', '- Source URL, SHA256, publication revision and locator retained in every approved fact; local original-PDF paths recorded in source metadata.', '- Both engine and frame indexes reconcile to table row counts and diagram part numbers. Raw duplicated rows and case-only aliases retained.', '- No KTM specifications or cross-year values automatically inherited.']
(P/'COVERAGE.md').write_text('\n'.join(lines)+'\n')
